#!/usr/bin/env python3
"""External, source-preserving runtime for the frozen task-tracker demo."""
import argparse
import hashlib
import json
import os
import subprocess
import sys
import time
import unittest
import urllib.request
import xml.etree.ElementTree as ET
from pathlib import Path

OUTPUTS = Path(__file__).resolve().parent.parent
APP = Path(os.environ.get("TT_APP", str(Path.home() / "app"))).resolve()
RUNTIME = Path(os.environ.get("TT_RUNTIME", str(Path.home() / "runtime"))).resolve()
NETWORK, DB, WEB = "tt-demo-net", "tt-demo-db", "tt-demo-app"
BASE_URL = "http://127.0.0.1:8080"


def run(args, **kwargs):
    return subprocess.run(args, check=True, text=True, **kwargs)


def podman(*args, **kwargs):
    return run(["podman", *args], **kwargs)


def integrity():
    run([sys.executable, str(OUTPUTS / "harness/check-frozen-app.py"), str(APP)])


def lock():
    data = json.loads((OUTPUTS / "_campaign/runtime-lock.json").read_text())
    for name, digest in data["jars"].items():
        if hashlib.sha256((RUNTIME / name).read_bytes()).hexdigest() != digest:
            raise RuntimeError("Runtime jar hash mismatch: " + name)
    return data


def remove():
    subprocess.run(["podman", "rm", "-f", "-v", WEB, DB], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def sql(query, readonly=True):
    user = "oracle_ro" if readonly else "tracker"
    return podman("exec", "-e", "PGPASSWORD=" + user, DB, "psql", "-h", "127.0.0.1", "-U", user,
                  "-d", "tracker", "-v", "ON_ERROR_STOP=1", "-Atc", query, capture_output=True).stdout.strip()


def start():
    integrity()
    config = lock()
    remove()
    if subprocess.run(["podman", "network", "exists", NETWORK]).returncode:
        podman("network", "create", NETWORK, stdout=subprocess.DEVNULL)
    db_args = ["run", "-d", "--pull=never", "--name", DB, "--network", NETWORK,
               "-e", "POSTGRES_DB=tracker", "-e", "POSTGRES_USER=tracker", "-e", "POSTGRES_PASSWORD=tracker"]
    for index, name in enumerate(("schema.sql", "seed.sql", "oracle-ro.sql"), 1):
        db_args.extend(["-v", f"{APP}/src/main/resources/db/{name}:/docker-entrypoint-initdb.d/{index:02}-{name}:ro"])
    podman(*db_args, config["images"]["postgres"], stdout=subprocess.DEVNULL)
    for _ in range(45):
        try:
            if sql("SELECT count(*) FROM task") == "4":
                break
        except subprocess.CalledProcessError:
            pass
        time.sleep(1)
    else:
        raise RuntimeError("Seeded PostgreSQL did not become ready")
    coverage = OUTPUTS / "reports/coverage"
    coverage.mkdir(parents=True, exist_ok=True)
    podman("run", "-d", "--pull=never", "--name", WEB, "--network", NETWORK,
           "-p", "127.0.0.1:8080:8080", "-e", f"DB_URL=jdbc:postgresql://{DB}:5432/tracker",
           "-e", "DB_USER=tracker", "-e", "DB_PASSWORD=tracker",
           "-e", "CATALINA_OPTS=-javaagent:/runtime/jacocoagent.jar=output=tcpserver,address=127.0.0.1,port=6300,dumponexit=false",
           "-v", f"{APP}:/app-source:ro", "-v", f"{RUNTIME}:/runtime:ro",
